import{_ as l,a8 as a,o as n,c as o,ah as i,K as e}from"./chunks/framework.DX2Vcg1x.js";import"./chunks/theme.BzIrHAwa.js";const I=JSON.parse('{"title":"AI 产业格局","description":"","frontmatter":{"title":"AI 产业格局","abstract":"AI 产业围绕大模型形成的三层生态格局，涵盖基础设施层、模型层与应用层的分工、代表厂商与商业化趋势。","created":"2026-07-10T00:00:00.000Z","tags":["大模型","产业","趋势"],"type":"概念解释","category":["🤖 AI大模型","AI 产业与概览"]},"headers":[],"relativePath":"vault/Knowledge/AI/AI 产业格局.md","filePath":"vault/Knowledge/AI/AI 产业格局.md","lastUpdated":1790655645000}'),h={name:"vault/Knowledge/AI/AI 产业格局.md"};function s(c,t,_,b,A,g){const r=a("NolebaseGitContributors"),d=a("NolebaseGitChangelog");return n(),o("div",null,[t[0]||(t[0]=i('<h1 id="ai-产业格局" tabindex="-1">AI 产业格局 <a class="header-anchor" href="#ai-产业格局" aria-label="Permalink to “AI 产业格局”">​</a></h1><p>当前 AI 产业围绕<strong>大模型</strong>形成三层生态：基础设施、模型层、应用层。</p><h2 id="三层结构" tabindex="-1">三层结构 <a class="header-anchor" href="#三层结构" aria-label="Permalink to “三层结构”">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>核心玩家</th><th>商业模式</th></tr></thead><tbody><tr><td>基础设施</td><td>NVIDIA、AWS、Azure、Google Cloud</td><td>卖算力（GPU/TPU）、云服务</td></tr><tr><td>模型层</td><td>OpenAI（GPT）、Anthropic（Claude）、Meta（Llama）、Google（Gemini）、国内大厂</td><td>闭源 API 收费、开源模型生态</td></tr><tr><td>应用层</td><td>垂直领域 SaaS、企业自研、AI Agent 创业公司</td><td>订阅制、按调用量、项目制</td></tr></tbody></table><h2 id="关键趋势" tabindex="-1">关键趋势 <a class="header-anchor" href="#关键趋势" aria-label="Permalink to “关键趋势”">​</a></h2><h3 id="_1-闭源-vs-开源" tabindex="-1">1. 闭源 vs 开源 <a class="header-anchor" href="#_1-闭源-vs-开源" aria-label="Permalink to “1. 闭源 vs 开源”">​</a></h3><ul><li><strong>闭源</strong>：OpenAI、Anthropic 追求性能领先，API 化服务</li><li><strong>开源</strong>：Meta（Llama）、Mistral、国内大厂（Qwen、Baichuan）推动生态，催生私有化部署</li></ul><h3 id="_2-垂直化" tabindex="-1">2. 垂直化 <a class="header-anchor" href="#_2-垂直化" aria-label="Permalink to “2. 垂直化”">​</a></h3><p>通用大模型 → 行业大模型（金融、医疗、法律、教育）→ 企业专属模型。</p><h3 id="_3-多模态融合" tabindex="-1">3. 多模态融合 <a class="header-anchor" href="#_3-多模态融合" aria-label="Permalink to “3. 多模态融合”">​</a></h3><p>文本、图像、语音、视频统一建模（GPT-4V、Gemini 1.5、Sora）。</p><h3 id="_4-智能体-agent-生态" tabindex="-1">4. 智能体（Agent）生态 <a class="header-anchor" href="#_4-智能体-agent-生态" aria-label="Permalink to “4. 智能体（Agent）生态”">​</a></h3><p>AI 自主规划、使用工具、联网搜索、执行任务，成为应用层新形态。</p><h2 id="国内格局" tabindex="-1">国内格局 <a class="header-anchor" href="#国内格局" aria-label="Permalink to “国内格局”">​</a></h2><table tabindex="0"><thead><tr><th>玩家</th><th>模型</th><th>定位</th></tr></thead><tbody><tr><td>百度</td><td>文心一言</td><td>全栈（云+模型+应用）</td></tr><tr><td>阿里</td><td>通义千问</td><td>云服务 + 开源</td></tr><tr><td>腾讯</td><td>混元</td><td>内部业务 + 对外 API</td></tr><tr><td>字节</td><td>云雀</td><td>内容生成 + 豆包</td></tr><tr><td>创业公司</td><td>智谱、月之暗面、零一万物</td><td>专注模型层或应用层</td></tr></tbody></table><h2 id="挑战" tabindex="-1">挑战 <a class="header-anchor" href="#挑战" aria-label="Permalink to “挑战”">​</a></h2><ul><li><strong>算力依赖</strong>：GPU 卡脖子风险</li><li><strong>数据合规</strong>：高质量数据获取与版权</li><li><strong>成本</strong>：训练/推理开销巨大</li><li><strong>安全对齐</strong>：幻觉、偏见、滥用</li></ul>',17)),e(r),e(d)])}const P=l(h,[["render",s]]);export{I as __pageData,P as default};
